 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState } from "react";
import { getNpsCategory, formatDateTime, isFormValid } from "../utils/fields";
import "./EvaluationForm.css";

declare const window: Window & { g_ck: string };

export function EvaluationForm() {
 const [starRating, setStarRating] = useState(0);
 const [hoverStar, setHoverStar] = useState(0);
 const [demandResolved, setDemandResolved] = useState<boolean | null>(null);
 const [npsScore, setNpsScore] = useState<number | null>(null);
 const [comments, setComments] = useState("");
 const [submitted, setSubmitted] = useState(false);
 const [submitting, setSubmitting] = useState(false);

 const handleSubmit = async () => {
 if (!isFormValid(starRating, demandResolved, npsScore)) return;
 setSubmitting(true);

 const body = {
 star_rating: starRating,
 demand_resolved: demandResolved,
 nps_score: npsScore,
 comments: comments || "",
 nps_category: getNpsCategory(npsScore!),
 evaluation_date: formatDateTime(new Date())
 };

 try {
 await fetch("/api/now/table/x_2049102_bnb_av_0_evaluation", {
 method: "POST",
 headers: {
 "X-UserToken": window.g_ck,
 "Content-Type": "application/json"
 },
 body: JSON.stringify(body)
 });
 setSubmitted(true);
 } catch {
 setSubmitting(false);
 }
 };

 if (submitted) {
 return (
 <div className="eval-container">
 <div className="eval-card eval-success">
 <div className="success-icon">&#x2714;</div>
 <h2>Obrigado pela sua avalia&#xE7;&#xE3;o!</h2>
 <p>Sua opini&#xE3;o &#xE9; muito importante para melhorarmos nossos servi&#xE7;os.</p>
 </div>
 </div>
 );
 }

 return (
 <div className="eval-container">
 <div className="eval-card">
 <header className="eval-header">
 <h1>Sua opini&#xE3;o &#xE9; importante</h1>
 <p>Responda brevemente para melhorarmos nossos servi&#xE7;os.</p>
 </header>

 <section className="eval-section">
 <label className="eval-label">
 O colaborador o atendeu com presteza e cordialidade?
 </label>
 <div className="star-row">
 {[1, 2, 3, 4, 5].map((star) => (
 <span
 key={star}
 className={`star ${star <= (hoverStar || starRating) ? "star-filled" : "star-empty"}`}
 onClick={() => setStarRating(star)}
 onMouseEnter={() => setHoverStar(star)}
 onMouseLeave={() => setHoverStar(0)}
 >
 &#x2605;
 </span>
 ))}
 </div>
 </section>

 <section className="eval-section">
 <label className="eval-label">A sua demanda foi atendida?</label>
 <div className="yesno-row">
 <span
 className={`yesno-btn ${demandResolved === true ? "yesno-yes-active" : ""}`}
 onClick={() => setDemandResolved(true)}
 >
 <span className="yesno-icon">&#x2713;</span> Sim
 </span>
 <span
 className={`yesno-btn ${demandResolved === false ? "yesno-no-active" : ""}`}
 onClick={() => setDemandResolved(false)}
 >
 <span className="yesno-icon">&#x2717;</span> N&#xE3;o
 </span>
 </div>
 </section>

 <section className="eval-section">
 <label className="eval-label">
 Voc&#xEA; recomenda o BNB para outros clientes?
 </label>
 <div className="nps-row">
 {Array.from({ length: 11 }, (_, i) => i).map((n) => (
 <span
 key={n}
 className={`nps-btn ${npsScore === n ? "nps-active" : ""}`}
 onClick={() => setNpsScore(n)}
 >
 {n}
 </span>
 ))}
 </div>
 <div className="nps-labels">
 <span>N&#xC3;O RECOMENDO</span>
 <span>RECOMENDO MUITO</span>
 </div>
 </section>

 <section className="eval-section">
 <label className="eval-label">
 Deixe sua cr&#xED;tica ou sugest&#xE3;o (opcional):
 </label>
 <textarea
 className="eval-textarea"
 placeholder="Escreva aqui sua opini&#xE3;o..."
 value={comments}
 onChange={(e) => setComments(e.target.value)}
 rows={4}
 />
 </section>

 <div className="eval-submit">
 <button
 className="submit-btn"
 disabled={!isFormValid(starRating, demandResolved, npsScore) || submitting}
 onClick={handleSubmit}
 type="button"
 >
 {submitting ? "Enviando..." : "Enviar Avalia\u00e7\u00e3o \u203A"}
 </button>
 </div>

 <p className="eval-privacy">
 Ao enviar, voc&#xEA; concorda com nossos termos de privacidade e uso de dados.
 </p>
 </div>
 </div>
 );
}
","import React, { useState, useEffect } from "react";
import "./DashboardView.css";

interface Evaluation {
 star_rating: { value: string; display_value: string };
 demand_resolved: { value: string; display_value: string };
 nps_score: { value: string; display_value: string };
 nps_category: { value: string; display_value: string };
 evaluation_date: { value: string; display_value: string };
}

interface KPIData {
 totalCount: number;
 avgStarRating: number;
 pctResolved: number;
 avgNPS: number;
 promoters: number;
 neutrals: number;
 detractors: number;
 npsZone: string;
 npsScore: number;
 unresolvedCount: number;
 criticalCount: number;
}

function computeKPIs(records: Evaluation[]): KPIData {
 const total = records.length;
 if (total === 0) {
 return {
 totalCount: 0, avgStarRating: 0, pctResolved: 0, avgNPS: 0,
 promoters: 0, neutrals: 0, detractors: 0,
 npsZone: "Sem dados", npsScore: 0, unresolvedCount: 0, criticalCount: 0
 };
 }

 let starSum = 0, npsSum = 0, resolvedCount = 0;
 let promoterCount = 0, neutralCount = 0, detractorCount = 0;
 let unresolvedCount = 0, criticalCount = 0;

 records.forEach(r => {
 const star = parseInt(r.star_rating.value) || 0;
 const nps = parseInt(r.nps_score.value) || 0;
 const resolved = r.demand_resolved.value === "true" || r.demand_resolved.value === "1";

 starSum += star;
 npsSum += nps;
 if (resolved) resolvedCount++;
 else unresolvedCount++;
 if (nps >= 9) promoterCount++;
 else if (nps >= 7) neutralCount++;
 else detractorCount++;
 if (nps < 5) criticalCount++;
 });

 const pctPromoters = (promoterCount / total) * 100;
 const pctDetractors = (detractorCount / total) * 100;
 const npsScore = pctPromoters - pctDetractors;

 let npsZone = "Crítica";
 if (npsScore > 75) npsZone = "Excelente";
 else if (npsScore >= 50) npsZone = "Muito Boa";
 else if (npsScore >= 0) npsZone = "Razoável";

 return {
 totalCount: total,
 avgStarRating: starSum / total,
 pctResolved: (resolvedCount / total) * 100,
 avgNPS: npsSum / total,
 promoters: pctPromoters,
 neutrals: (neutralCount / total) * 100,
 detractors: pctDetractors,
 npsZone,
 npsScore,
 unresolvedCount,
 criticalCount
 };
}

interface Props {
 onNavigate: (view: string, title?: string) => void;
}

export default function DashboardView({ onNavigate }: Props) {
 const [kpis, setKpis] = useState<KPIData | null>(null);
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 fetch(
 "/api/now/table/x_2049102_bnb_av_0_evaluation?sysparm_display_value=all&sysparm_limit=1000",
 { headers: { Accept: "application/json", "X-UserToken": (window as any).g_ck } }
 )
 .then(res => res.json())
 .then(data => {
 setKpis(computeKPIs(data.result || []));
 setLoading(false);
 })
 .catch(() => setLoading(false));
 }, []);

 if (loading) {
 return <div className="admin-loading">Carregando dados...</div>;
 }

 if (!kpis) {
 return <div className="admin-loading">Erro ao carregar dados.</div>;
 }

 return (
 <div className="admin-dashboard">
 <header className="admin-header">
 <h1>Painel Administrativo - Avaliações BNB</h1>
 <span
 className="admin-nav-link"
 onClick={() => onNavigate("list", "Lista de Avaliações")}
 >
 Ver todas as avaliações →
 </span>
 </header>

 <section className="kpi-grid">
 <div className="kpi-card">
 <div className="kpi-label">Nota Média (Estrelas)</div>
 <div className="kpi-value star">
 {"★".repeat(Math.round(kpis.avgStarRating))}
 {"☆".repeat(5 - Math.round(kpis.avgStarRating))}
 </div>
 <div className="kpi-detail">{kpis.avgStarRating.toFixed(1)} / 5.0</div>
 </div>

 <div className="kpi-card">
 <div className="kpi-label">Demandas Resolvidas</div>
 <div className={`kpi-value ${kpis.pctResolved >= 70 ? "positive" : "critical"}`}>
 {kpis.pctResolved.toFixed(1)}%
 </div>
 <div className="kpi-detail">Sim vs Não</div>
 </div>

 <div className="kpi-card">
 <div className="kpi-label">NPS Médio</div>
 <div className={`kpi-value ${kpis.avgNPS >= 7 ? "positive" : kpis.avgNPS >= 5 ? "neutral" : "critical"}`}>
 {kpis.avgNPS.toFixed(1)}
 </div>
 <div className="kpi-detail">Escala 0-10</div>
 </div>

 <div className="kpi-card">
 <div className="kpi-label">Classificação NPS</div>
 <div className={`kpi-value ${kpis.npsScore > 50 ? "positive" : kpis.npsScore >= 0 ? "neutral" : "critical"}`}>
 {kpis.npsZone}
 </div>
 <div className="kpi-detail">
 Score: {kpis.npsScore.toFixed(0)} | P:{kpis.promoters.toFixed(0)}% N:{kpis.neutrals.toFixed(0)}% D:{kpis.detractors.toFixed(0)}%
 </div>
 </div>
 </section>

 <section className="summary-grid">
 <div className="summary-card">
 <div className="summary-icon">📊</div>
 <div className="summary-value">{kpis.totalCount}</div>
 <div className="summary-label">Total de Avaliações</div>
 </div>

 <div className="summary-card warning" onClick={() => onNavigate("list", "Demandas Não Resolvidas")}>
 <div className="summary-icon">⚠️</div>
 <div className="summary-value">{kpis.unresolvedCount}</div>
 <div className="summary-label">Demandas Não Resolvidas</div>
 </div>

 <div className="summary-card danger">
 <div className="summary-icon">🚨</div>
 <div className="summary-value">{kpis.criticalCount}</div>
 <div className="summary-label">Avaliações Críticas (NPS &lt; 5)</div>
 </div>
 </section>
 </div>
 );
}
