","/* BNB Evaluation Form Styles */
:root {
 --bnb-primary: #8B1A3A;
 --bnb-primary-hover: #A02050;
 --bnb-star-filled: #F5A623;
 --bnb-star-empty: #D1D1D1;
 --bnb-bg: #F8F8F8;
 --bnb-card-bg: #FFFFFF;
 --bnb-text: #333333;
 --bnb-text-light: #666666;
 --bnb-border: #E0E0E0;
 --bnb-success-green: #2E7D32;
 --bnb-error-red: #C62828;
}

* {
 box-sizing: border-box;
 margin: 0;
 padding: 0;
}

body {
 font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
 background-color: var(--bnb-bg);
 color: var(--bnb-text);
 line-height: 1.5;
}

.eval-container {
 display: flex;
 justify-content: center;
 align-items: flex-start;
 min-height: 100vh;
 padding: 24px 16px;
}

.eval-card {
 background: var(--bnb-card-bg);
 border-radius: 12px;
 box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
 padding: 32px 24px;
 width: 100%;
 max-width: 520px;
}

/* Header */
.eval-header {
 text-align: center;
 margin-bottom: 28px;
}

.eval-header h1 {
 font-size: 1.5rem;
 font-weight: 700;
 color: var(--bnb-primary);
 margin-bottom: 8px;
}

.eval-header p {
 font-size: 0.95rem;
 color: var(--bnb-text-light);
}

/* Sections */
.eval-section {
 margin-bottom: 24px;
}

.eval-label {
 display: block;
 font-size: 0.95rem;
 font-weight: 600;
 color: var(--bnb-text);
 margin-bottom: 12px;
}

/* Star Rating */
.star-row {
 display: flex;
 gap: 8px;
 justify-content: center;
}

.star {
 font-size: 2.2rem;
 cursor: pointer;
 transition: transform 0.15s ease, color 0.15s ease;
 user-select: none;
}

.star:hover {
 transform: scale(1.15);
}

.star-filled {
 color: var(--bnb-star-filled);
}

.star-empty {
 color: var(--bnb-star-empty);
}

/* Yes/No Buttons */
.yesno-row {
 display: flex;
 gap: 16px;
 justify-content: center;
}

.yesno-btn {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 padding: 10px 24px;
 border: 2px solid var(--bnb-border);
 border-radius: 24px;
 font-size: 0.95rem;
 font-weight: 500;
 cursor: pointer;
 transition: all 0.2s ease;
 user-select: none;
}

.yesno-btn:hover {
 border-color: var(--bnb-primary);
}

.yesno-icon {
 font-size: 1.1rem;
 font-weight: 700;
}

.yesno-yes-active {
 border-color: var(--bnb-success-green);
 background-color: #E8F5E9;
 color: var(--bnb-success-green);
}

.yesno-no-active {
 border-color: var(--bnb-error-red);
 background-color: #FFEBEE;
 color: var(--bnb-error-red);
}

/* NPS Scale */
.nps-row {
 display: flex;
 gap: 6px;
 justify-content: center;
 flex-wrap: wrap;
}

.nps-btn {
 width: 36px;
 height: 36px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 border: 2px solid var(--bnb-border);
 border-radius: 8px;
 font-size: 0.85rem;
 font-weight: 600;
 cursor: pointer;
 transition: all 0.15s ease;
 user-select: none;
}

.nps-btn:hover {
 border-color: var(--bnb-primary);
 background-color: #FDF0F4;
}

.nps-active {
 border-color: var(--bnb-primary);
 background-color: var(--bnb-primary);
 color: #FFFFFF;
}

.nps-labels {
 display: flex;
 justify-content: space-between;
 margin-top: 8px;
 font-size: 0.7rem;
 font-weight: 600;
 color: var(--bnb-text-light);
 text-transform: uppercase;
 letter-spacing: 0.5px;
}

/* Textarea */
.eval-textarea {
 width: 100%;
 padding: 12px 16px;
 border: 2px solid var(--bnb-border);
 border-radius: 8px;
 font-size: 0.95rem;
 font-family: inherit;
 resize: vertical;
 transition: border-color 0.2s ease;
 line-height: 1.5;
}

.eval-textarea:focus {
 outline: none;
 border-color: var(--bnb-primary);
}

.eval-textarea::placeholder {
 color: #AAAAAA;
}

/* Submit */
.eval-submit {
 text-align: center;
 margin-top: 8px;
 margin-bottom: 16px;
}

.submit-btn {
 background-color: var(--bnb-primary);
 border: none;
 border-radius: 24px;
 padding: 12px 32px;
 font-size: 1rem;
 font-weight: 600;
 color: #FFFFFF;
 cursor: pointer;
 transition: background-color 0.2s ease;
 min-width: 200px;
 font-family: inherit;
}

.submit-btn:hover {
 background-color: var(--bnb-primary-hover);
}

.submit-btn:disabled {
 opacity: 0.5;
 cursor: not-allowed;
}

/* Privacy */
.eval-privacy {
 text-align: center;
 font-size: 0.8rem;
 color: var(--bnb-text-light);
 line-height: 1.4;
}

/* Success State */
.eval-success {
 text-align: center;
 padding: 48px 24px;
}

.success-icon {
 font-size: 3rem;
 color: var(--bnb-success-green);
 margin-bottom: 16px;
}

.eval-success h2 {
 font-size: 1.4rem;
 color: var(--bnb-primary);
 margin-bottom: 12px;
}

.eval-success p {
 font-size: 0.95rem;
 color: var(--bnb-text-light);
}

/* Responsive */
@media (max-width: 480px) {
 .eval-card {
 padding: 24px 16px;
 border-radius: 8px;
 }

 .eval-header h1 {
 font-size: 1.3rem;
 }

 .star {
 font-size: 1.8rem;
 }

 .nps-btn {
 width: 30px;
 height: 30px;
 font-size: 0.75rem;
 }

 .nps-row {
 gap: 4px;
 }

 .yesno-btn {
 padding: 8px 18px;
 font-size: 0.9rem;
 }
}
",".admin-dashboard {
 font-family: var(--now-font-family, "Lato", sans-serif);
 padding: 0;
 background: #f4f5f7;
 min-height: 100vh;
}

.admin-header {
 background: #8B1A3A;
 color: #fff;
 padding: 20px 32px;
 display: flex;
 align-items: center;
 justify-content: space-between;
}

.admin-header h1 {
 margin: 0;
 font-size: 20px;
 font-weight: 600;
}

.admin-nav-link {
 color: #ffd6e0;
 cursor: pointer;
 font-size: 14px;
 text-decoration: underline;
}

.admin-nav-link:hover {
 color: #fff;
}

.admin-loading {
 display: flex;
 align-items: center;
