 color: #555;
}

.kpi-grid {
 display: grid;
 grid-template-columns: repeat(4, 1fr);
 gap: 20px;
 padding: 24px 32px;
}

.kpi-card {
 background: #fff;
 border-radius: 12px;
 padding: 24px;
 box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
 text-align: center;
}

.kpi-label {
 font-size: 13px;
 color: #666;
 text-transform: uppercase;
 letter-spacing: 0.5px;
 margin-bottom: 12px;
}

.kpi-value {
 font-size: 32px;
 font-weight: 700;
 margin-bottom: 8px;
}

.kpi-value.star {
 color: #f5a623;
 font-size: 28px;
}

.kpi-value.positive {
 color: #2e7d32;
}

.kpi-value.neutral {
 color: #f57c00;
}

.kpi-value.critical {
 color: #c62828;
}

.kpi-detail {
 font-size: 12px;
 color: #888;
}

.summary-grid {
 display: grid;
 grid-template-columns: repeat(3, 1fr);
 gap: 20px;
 padding: 0 32px 32px;
}

.summary-card {
 background: #fff;
 border-radius: 12px;
 padding: 24px;
 box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
 text-align: center;
 transition: transform 0.15s;
}

.summary-card.warning {
 cursor: pointer;
 border-left: 4px solid #f57c00;
}

.summary-card.warning:hover {
 transform: translateY(-2px);
}

.summary-card.danger {
 border-left: 4px solid #c62828;
}

.summary-icon {
 font-size: 28px;
 margin-bottom: 8px;
}

.summary-value {
 font-size: 36px;
 font-weight: 700;
 color: #333;
}

.summary-label {
 font-size: 13px;
 color: #666;
 margin-top: 8px;
}

@media (max-width: 1024px) {
 .kpi-grid {
 grid-template-columns: repeat(2, 1fr);
 }
}

@media (max-width: 600px) {
 .kpi-grid,
 .summary-grid {
 grid-template-columns: 1fr;
 }

 .admin-header {
 flex-direction: column;
 gap: 8px;
 text-align: center;
 }
}
